    checkCase(Api.echoNatBox(box) == box)
    checkCase(Api.echoAgain(NatBoxAgain(n(4), n(1))) == NatBoxAgain(n(4), n(1)))
    checkCase(Api.echoTextBox(TextBox(greeting, n(0))) == TextBox(greeting, n(0)))
    val left: LeftBox = Api.echoLeft(LeftBox(n(5), n(2)))
    val right: RightBox = Api.echoRight(RightBox(n(6), n(3)))
    checkCase(left == LeftBox(n(5), n(2)))
    checkCase(right == RightBox(n(6), n(3)))
    checkCase(LeftBox::class != RightBox::class && LeftBox::class != NatBox::class)
    val specializedBoxes: Array<NatBox> = Api.echoBoxes(boxes)
    checkCase(specializedBoxes.size == 3 && specializedBoxes[2].value() == huge && Api.echoBoxes(arrayOf()).isEmpty())
    val specializedOptional: Option<Array<NatBox>> = Api.echoOptionalBoxes(Option.some(boxes))
    checkCase(specializedOptional.isSome() && specializedOptional.value()[2].value() == huge)
    checkCase(!Api.echoOptionalBoxes(Option.none()).isSome())
    checkCase(Api.echoOptionalBoxes(Option.some(arrayOf())).value().isEmpty())
    val specializedNats: Array<BigInteger> = Api.echoNats(arrayOf(n(0), huge))
    checkCase(specializedNats.size == 2 && specializedNats[1] == huge && Api.echoNats(arrayOf()).isEmpty())
    val specializedNat: Option<BigInteger> = Api.echoOptionalNat(Option.some(huge))
    checkCase(specializedNat.isSome() && specializedNat.value() == huge && !Api.echoOptionalNat(Option.none()).isSome())
    checkCase(rejected { Api.echoLeft(LeftBox(n(-1), n(0))) })
    checkCase(rejected { Api.echoOptionalNat(Option.some(n(-1))) })
    checkCase(Api.echoLeft(LeftBox(n(7), n(0))).value() == n(7))
